async function generateReport() { setUpload('Finalizing report…', 'Calculating authoritative server-side metrics and preserving this report snapshot.'); const response = await fetch(`/api/report-processes/${encodeURIComponent(state.processId)}/finalize`, { method: 'POST' }); const result = await response.json(); if (!response.ok) return notice('Report could not be generated', result.message, true); sessionStorage.removeItem('deliveryiq-process-id'); state.processId = null; state.result = null; setUploadLocked(null); setUpload('Report generated successfully', 'Your report is ready to view.'); history.pushState({}, '', '/reports'); page('reports'); await loadReports(); viewReport(result.report.reportId); }

