function closeMobileMenu() { const menu = $('#mobile-navigation'); const backdrop = $('#mobile-menu-backdrop'); if (!menu) return; menu.hidden = true; backdrop.hidden = true; $('.menu-button').setAttribute('aria-expanded', 'false'); document.body.classList.remove('mobile-menu-open'); }
function openMobileMenu() { const menu = $('#mobile-navigation'); const backdrop = $('#mobile-menu-backdrop'); if (!menu) return; menu.hidden = false; backdrop.hidden = false; $('.menu-button').setAttribute('aria-expanded', 'true'); document.body.classList.add('mobile-menu-open'); menu.querySelector('.mobile-menu-close').focus(); }
(function setupMobileMenu() { const menu = $('#mobile-navigation'); const links = $('#mobile-navigation-links'); const button = $('.menu-button'); if (!menu || !links || !button) return; document.querySelectorAll('.sidebar .nav-link').forEach((link) => { const clone = link.cloneNode(true); clone.addEventListener('click', closeMobileMenu); links.append(clone); }); button.addEventListener('click', () => menu.hidden ? openMobileMenu() : closeMobileMenu()); $('#mobile-menu-backdrop').addEventListener('click', closeMobileMenu); menu.querySelector('.mobile-menu-close').addEventListener('click', closeMobileMenu); document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && !menu.hidden) closeMobileMenu(); }); }());

// Universal Report is intentionally a presentation layer: the API supplies current
// projections, status categories, grouping, and historical observations.
function universalFormatNumber(value) { return Number.isFinite(Number(value)) ? Number(value).toLocaleString('en-IN') : '—'; }
function universalFormatCurrency(value) { return Number.isFinite(Number(value)) ? new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(value)) : '—'; }
function universalFormatDate(value, time = false) { const date = value ? new Date(value.length === 10 ? `${value}T00:00:00` : value) : null; if (!date || Number.isNaN(date.getTime())) return '—'; return new Intl.DateTimeFormat('en-IN', time ? { day: '2-digit', month: 'short', year: 'numeric', hour: 'numeric', minute: '2-digit' } : { day: '2-digit', month: 'short', year: 'numeric' }).format(date); }
function universalErrorMessage(response, payload) { if (response.status === 401) return 'Your session has expired. Please sign in again.'; if (response.status === 403) return 'You do not have access to Universal Report.'; if (response.status === 404) return 'This order is no longer available.'; if (response.status === 422) return payload?.message || 'Please check the filters and try again.'; if (response.status === 429) return payload?.message || 'Too many requests. Please try again later.'; return 'Universal Report could not be loaded. Please try again.'; }
async function universalFetch(url, options = {}) { const response = await fetch(url, options); const payload = await response.json().catch(() => ({})); if (!response.ok) { const error = new Error(universalErrorMessage(response, payload)); error.status = response.status; throw error; } return payload; }
function universalParams({ includePage = true } = {}) { const form = $('#universal-filters'); const params = new URLSearchParams(); for (const [name, value] of new FormData(form)) if (value) params.set(name, value); if (includePage) { params.set('page', String(state.universal.page)); params.set('limit', String(state.universal.limit)); } return params; }
function universalStatusBadge(status, category) { const wrap = el('span', undefined, 'universal-statuses'); wrap.append(el('span', status || 'No status', 'status-badge'), el('span', category || 'Uncategorized', 'category-badge')); return wrap; }
function universalProducts(products) { const list = el('ul', undefined, 'universal-products'); if (!products?.length) { list.append(el('li', 'No product information')); return list; } products.forEach((product) => { const name = product.originalProductName || product.normalizedProductName || 'Unnamed product'; list.append(el('li', `${name}${Number.isFinite(Number(product.quantity)) ? ` × ${universalFormatNumber(product.quantity)}` : ''}`)); }); return list; }
function universalSkeleton(target, type = 'orders') { clear(target); if (type === 'summary') { for (let index = 0; index < 4; index += 1) target.append(el('div', undefined, 'universal-card skeleton')); return; } const wrap = el('div', undefined, 'universal-table-wrap'); const table = document.createElement('table'); table.className = 'universal-table'; const body = document.createElement('tbody'); for (let index = 0; index < 6; index += 1) { const row = document.createElement('tr'); for (let cell = 0; cell < 7; cell += 1) row.append(el('td', '', 'skeleton-cell')); body.append(row); } table.append(body); wrap.append(table); target.append(wrap); }
function universalSummary(summary) { if (summary) { const rto = Number(summary.byStatusCategory?.RTO || 0); summary = { ...summary, rtoOrders: summary.rtoOrders ?? rto, rtoPercentage: summary.rtoPercentage ?? (summary.totalOrders ? Number((rto * 100 / summary.totalOrders).toFixed(2)) : 0) }; } const target = $('#universal-summary'); clear(target); if (!summary || !summary.totalOrders) { target.append(el('div', 'No current order summary is available for these filters.', 'universal-no-summary')); return; } const metrics = [['Total orders', universalFormatNumber(summary.totalOrders)], ['Total value', universalFormatCurrency(summary.totalValue)], ['Total quantity', universalFormatNumber(summary.totalQuantity)], ['RTO / attention', `${universalFormatNumber(summary.rtoOrders || 0)} (${summary.rtoPercentage || 0}%)`]]; metrics.forEach(([label, value]) => { const card = el('article', undefined, 'universal-card'); card.append(el('span', label), el('strong', value)); target.append(card); }); }
function universalAnalytics(analytics) { const target = $('#universal-analytics'); clear(target); if (!analytics?.summary?.totalOrders) { target.append(el('p', 'No analytics are available for these filters.', 'universal-no-summary')); return; } const section = (title, copy) => { const card = el('article', undefined, 'universal-analytics-card'); card.append(el('h3', title)); if (copy) card.append(el('p', copy)); return card; }; const distribution = section('Status categories', 'Filtered current orders by backend-defined category.'); const bars = el('div', undefined, 'analytics-bars'); (analytics.statusCategories || []).forEach((item) => { const row = el('div', undefined, 'analytics-bar'); row.append(el('span', item.name), el('strong', `${universalFormatNumber(item.count)} · ${item.percentage}%`)); const meter = el('div', undefined, 'analytics-meter'); meter.setAttribute('role', 'progressbar'); meter.setAttribute('aria-label', `${item.name}: ${item.count} orders, ${item.percentage}%`); meter.setAttribute('aria-valuenow', String(item.percentage)); meter.append(el('i')); meter.lastChild.style.width = `${item.percentage}%`; row.append(meter); bars.append(row); }); distribution.append(bars); const statuses = section('Latest statuses'); const statusList = el('ul', undefined, 'analytics-list'); (analytics.statuses || []).forEach((item) => statusList.append(el('li', `${item.name} — ${universalFormatNumber(item.count)} (${item.percentage}%)`))); statuses.append(statusList); const trend = section('Orders by Order Date', 'Current orders grouped by their order date.'); const trendList = el('ul', undefined, 'analytics-list'); (analytics.trends || []).forEach((item) => trendList.append(el('li', `${universalFormatDate(item.date)} — ${universalFormatNumber(item.count)} orders · ${universalFormatCurrency(item.value)}`))); trend.append(trendList); const products = section('Top products', 'Product lines retain their own quantities.'); const productList = el('ol', undefined, 'analytics-list'); (analytics.products || []).forEach((item) => productList.append(el('li', `${item.name || 'Unmapped product'} — ${universalFormatNumber(item.quantity)} units · ${universalFormatNumber(item.orderCount)} orders · ${universalFormatCurrency(item.value)}`))); products.append(productList); const attention = section('Needs Attention', 'Objectively identified from the current status category.'); attention.append(el('p', analytics.attention?.length ? `RTO: ${universalFormatNumber(analytics.attention[0].count)} orders (${analytics.attention[0].percentage}%) · ${universalFormatCurrency(analytics.attention[0].value)}` : 'No RTO orders in the filtered current dataset.')); target.append(distribution, statuses, trend, products, attention); }
function universalHasActiveFilters() { const form = $('#universal-filters'); return ['search', 'status', 'statusCategory', 'fromDate', 'toDate', 'reportFromDate', 'reportToDate'].some((name) => Boolean(form.elements[name].value)); }
function universalEmpty(message, actionText) { const box = el('section', undefined, 'universal-empty'); box.append(el('div', '◎', 'empty-icon'), el('h3', actionText ? 'No orders match these filters' : 'Your Universal Report is ready when your first Delivery Report is completed.'), el('p', message)); if (actionText) { const button = el('button', actionText, 'button button-secondary'); button.type = 'button'; button.addEventListener('click', () => { $('#universal-clear-filters').click(); }); box.append(button); } return box; }
function universalOrders(orders) { const target = $('#universal-orders-content'); clear(target); if (!orders.length) { const filtered = universalHasActiveFilters(); target.append(universalEmpty(filtered ? 'Try clearing one or more filters, then search again.' : 'Your Universal Report will appear here after your first completed Delivery Report.', filtered ? 'Clear filters' : null)); return; }
 const wrap = el('div', undefined, 'universal-table-wrap'); const table = document.createElement('table'); table.className = 'universal-table'; const headers = ['Order ID', 'Order date', 'Latest status', 'Quantity', 'Value', 'Latest report', 'Last updated', '']; const head = document.createElement('thead'); const row = document.createElement('tr'); headers.forEach((label) => row.append(el('th', label))); head.append(row); const body = document.createElement('tbody'); orders.forEach((order) => { const tr = document.createElement('tr'); tr.append(el('th', order.canonicalOrderId || order.originalOrderId || '—')); tr.lastChild.scope = 'row'; tr.append(el('td', universalFormatDate(order.orderDate))); const status = el('td'); status.append(universalStatusBadge(order.originalStatus, order.statusCategory)); tr.append(status, el('td', universalFormatNumber(order.totalQuantity)), el('td', universalFormatCurrency(order.totalValue)), el('td', order.latestReportId || '—'), el('td', universalFormatDate(order.latestReportCompletedAt, true))); const action = el('button', 'View details', 'button button-secondary universal-detail-button'); action.type = 'button'; action.addEventListener('click', () => universalDetail(order.canonicalOrderId)); tr.append(el('td').appendChild(action).parentElement); body.append(tr); }); table.append(head, body); wrap.append(table); target.append(wrap);
 const cards = el('div', undefined, 'universal-order-cards'); orders.forEach((order) => { const card = el('article', undefined, 'universal-order-card'); card.append(el('h3', order.canonicalOrderId || order.originalOrderId || '—'), universalStatusBadge(order.originalStatus, order.statusCategory)); const meta = el('dl'); [['Order date', universalFormatDate(order.orderDate)], ['Quantity', universalFormatNumber(order.totalQuantity)], ['Value', universalFormatCurrency(order.totalValue)]].forEach(([label, value]) => { meta.append(el('dt', label), el('dd', value)); }); const action = el('button', 'View details', 'button button-secondary'); action.type = 'button'; action.addEventListener('click', () => universalDetail(order.canonicalOrderId)); card.append(meta, action); cards.append(card); }); target.append(cards); }
function universalPagination(pagination) { const nav = $('#universal-pagination'); clear(nav); if (!pagination || pagination.totalPages < 2) { nav.hidden = true; return; } nav.hidden = false; const previous = el('button', 'Previous', 'button button-secondary'); previous.type = 'button'; previous.disabled = pagination.page <= 1; previous.addEventListener('click', () => { state.universal.page -= 1; loadUniversal({ summary: false }); }); const next = el('button', 'Next', 'button button-secondary'); next.type = 'button'; next.disabled = pagination.page >= pagination.totalPages; next.addEventListener('click', () => { state.universal.page += 1; loadUniversal({ summary: false }); }); nav.append(previous, el('span', `Page ${pagination.page} of ${pagination.totalPages} · ${universalFormatNumber(pagination.total)} current orders`), next); }
async function loadUniversal({ summary = true } = {}) { state.universal.loading = true; const ordersTarget = $('#universal-orders-content'); const summaryTarget = $('#universal-summary'); const analyticsTarget = $('#universal-analytics'); if (!ordersTarget) return; if (state.universal.controller) state.universal.controller.abort(); state.universal.controller = new AbortController(); const controller = state.universal.controller; universalSkeleton(ordersTarget); if (summary) { universalSkeleton(summaryTarget, 'summary'); clear(analyticsTarget); analyticsTarget.append(el('p', 'Loading analytics…', 'universal-no-summary')); } $('#universal-result-summary').textContent = 'Loading current orders…'; try { const filterParams = universalParams({ includePage: false }); const requests = [universalFetch(`/api/universal/orders?${universalParams()}`, { signal: controller.signal })]; if (summary) requests.push(universalFetch(`/api/universal/summary?${filterParams}`, { signal: controller.signal }), universalFetch(`/api/universal/analytics?${filterParams}`, { signal: controller.signal })); const [orders, summaryPayload, analyticsPayload] = await Promise.all(requests); if (summaryPayload) universalSummary(summaryPayload.summary); if (analyticsPayload) universalAnalytics(analyticsPayload.analytics); universalOrders(orders.orders || []); universalPagination(orders.pagination); $('#universal-result-summary').textContent = `${universalFormatNumber(orders.pagination.total)} current order${orders.pagination.total === 1 ? '' : 's'}`; } catch (error) { if (error.name === 'AbortError') return; clear(ordersTarget); const failure = el('section', undefined, 'universal-empty universal-error'); failure.append(el('h3', 'Unable to load orders'), el('p', error.message)); const retry = el('button', 'Retry', 'button button-primary'); retry.type = 'button'; retry.addEventListener('click', () => loadUniversal({ summary })); failure.append(retry); ordersTarget.append(failure); if (summary) { clear(summaryTarget); summaryTarget.append(el('div', 'Summary is temporarily unavailable.', 'universal-no-summary')); clear(analyticsTarget); analyticsTarget.append(el('p', 'Analytics are temporarily unavailable. Use Refresh to retry.', 'universal-no-summary')); } } finally { if (state.universal.controller === controller) state.universal.loading = false; }
}
function universalDialog() { let dialog = $('#universal-detail-dialog'); if (dialog) return dialog; dialog = document.createElement('dialog'); dialog.id = 'universal-detail-dialog'; dialog.className = 'universal-dialog'; dialog.setAttribute('aria-labelledby', 'universal-detail-title'); document.body.append(dialog); dialog.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); }); return dialog; }
function universalDetailContent(order, history) { const content = document.createDocumentFragment(); const heading = el('div', undefined, 'universal-dialog-heading'); heading.append(el('div', undefined).append(el('p', 'CURRENT ORDER STATE', 'eyebrow'), el('h2', order.canonicalOrderId || order.originalOrderId || 'Order details')), el('button', '×', 'universal-dialog-close')); heading.querySelector('h2').id = 'universal-detail-title'; heading.querySelector('button').type = 'button'; heading.querySelector('button').setAttribute('aria-label', 'Close order details'); heading.querySelector('button').addEventListener('click', () => universalDialog().close()); content.append(heading); const grid = el('dl', undefined, 'universal-detail-grid'); [['Order date', universalFormatDate(order.orderDate)], ['Latest status', order.originalStatus || '—'], ['Status category', order.statusCategory || '—'], ['Quantity', universalFormatNumber(order.totalQuantity)], ['Value', universalFormatCurrency(order.totalValue)], ['Latest report', order.latestReportId || '—'], ['Last report update', universalFormatDate(order.latestReportCompletedAt, true)], ['Payment mode', order.paymentMode || '—'], ['Courier', order.courier || '—'], ['Source / store', order.orderSource || '—']].forEach(([label, value]) => grid.append(el('dt', label), el('dd', value))); content.append(grid); const products = el('section', undefined, 'universal-detail-section'); products.append(el('h3', 'Products in current state'), universalProducts(order.products)); content.append(products); const historySection = el('section', undefined, 'universal-history'); historySection.append(el('div', undefined).append(el('p', 'HISTORICAL OBSERVATIONS', 'eyebrow'), el('h3', 'Report history'))); if (!history?.occurrences?.length) historySection.append(el('p', 'No historical observations are available for this order.')); else { history.occurrences.forEach((item) => { const observation = el('article', undefined, 'history-observation'); observation.append(el('strong', `Report ${item.reportId || '—'}`), el('span', `Completed ${universalFormatDate(item.reportCompletedAt, true)}`), universalStatusBadge(item.originalStatus, item.statusCategory), el('span', `Order date: ${universalFormatDate(item.orderDate)} · Quantity: ${universalFormatNumber(item.totalQuantity)} · Value: ${universalFormatCurrency(item.totalValue)}`), universalProducts(item.products)); historySection.append(observation); }); if (history.pagination?.totalPages > 1) historySection.append(el('p', `Showing the latest ${history.occurrences.length} of ${history.pagination.total} historical observations.`)); } content.append(historySection); return content; }
async function universalDetail(orderId) { const dialog = universalDialog(); clear(dialog); dialog.append(el('div', 'Loading order details…', 'universal-dialog-loading')); dialog.showModal(); try { let detail = state.universal.detailCache.get(orderId); if (!detail) { const [orderPayload, history] = await Promise.all([universalFetch(`/api/universal/orders/${encodeURIComponent(orderId)}`), universalFetch(`/api/universal/orders/${encodeURIComponent(orderId)}/history?limit=25`)]); detail = { order: orderPayload.order, history }; state.universal.detailCache.set(orderId, detail); } clear(dialog); dialog.append(universalDetailContent(detail.order, detail.history)); } catch (error) { clear(dialog); const failure = el('div', undefined, 'universal-dialog-loading'); failure.append(el('h2', 'Order details unavailable'), el('p', error.message)); const close = el('button', 'Close', 'button button-secondary'); close.type = 'button'; close.addEventListener('click', () => dialog.close()); failure.append(close); dialog.append(failure); } }
async function universalExport() { const button = $('#universal-export'); const status = $('#universal-export-status'); if (button.disabled) return; button.disabled = true; button.textContent = 'Preparing export…'; status.textContent = 'Exporting current filtered orders…'; try { const response = await fetch(`/api/universal/export?${universalParams({ includePage: false })}`); if (!response.ok) { const payload = await response.json().catch(() => ({})); throw new Error(universalErrorMessage(response, payload)); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'deliveryiq-universal-current-orders.csv'; document.body.append(link); link.click(); link.remove(); URL.revokeObjectURL(url); status.textContent = 'Current filtered orders exported as CSV.'; } catch (error) { status.textContent = error.message || 'Export could not be completed. Please try again.'; } finally { button.disabled = false; button.textContent = 'Export CSV'; } }
(function setupUniversalReport() { const form = $('#universal-filters'); if (!form) return; choices(form.elements.statusCategory, state.config.statusCategories, 'All categories'); let timer; const search = form.elements.search; const scheduleSearch = () => { clearTimeout(timer); timer = setTimeout(() => { state.universal.page = 1; loadUniversal(); }, 320); }; search.addEventListener('input', () => { $('#universal-clear-search').hidden = !search.value; scheduleSearch(); }); $('#universal-clear-search').addEventListener('click', () => { search.value = ''; $('#universal-clear-search').hidden = true; state.universal.page = 1; loadUniversal(); search.focus(); }); form.addEventListener('submit', (event) => { event.preventDefault(); state.universal.page = 1; loadUniversal(); }); form.querySelectorAll('select,input[type="date"],input[name="status"]').forEach((input) => input.addEventListener('change', () => { state.universal.page = 1; loadUniversal(); })); $('#universal-clear-filters').addEventListener('click', () => { form.reset(); choices(form.elements.statusCategory, state.config.statusCategories, 'All categories'); $('#universal-clear-search').hidden = true; state.universal.page = 1; loadUniversal(); }); $('#universal-refresh').addEventListener('click', () => loadUniversal()); $('#universal-export').addEventListener('click', universalExport); }());
